out.btnType = btn.type;
out.btn = { w: btn.width, h: btn.height, fills: btn.fills, cornerRadius: btn.cornerRadius, effects: btn.effects };
const btnText = btn.findOne(n => n.type === "TEXT");
if (btnText) out.btnText = { chars: btnText.characters, font: btnText.fontName, fills: btnText.fills };
out.tfType = tf.type;
out.tf = { w: tf.width, h: tf.height };
const input = tf.findOne(n => n.name === "Input");
if (input) out.input = { fills: input.fills, radius: input.cornerRadius, strokes: input.strokes, strokeWeight: input.strokeWeight };
