if (ph) out.placeholder = { chars: ph.characters, font: ph.fontName, fills: ph.fills };
const lbl = tf.findOne(n => n.name === "Label");
if (lbl) out.label = { chars: lbl.characters, font: lbl.fontName, fills: lbl.fills };
// fonts
const fonts = figma.listAvailableFontsAsync ? await figma.listAvailableFontsAsync() : [];
const pick = (fam) => fonts.filter(f => f.fontName.family === fam).map(f => f.fontName.style);
out.volkhov = pick("Volkhov");
out.poppins = pick("Poppins").slice(0, 20);
// media components
